+func TestForwardUpstreamTTLExpiredReplyIsRouteRefused(t *testing.T) {
+	s := newStub(t, 0x06, false)
+	f := New(s.addr(), &stubCounter{})
+	addr, errc := forwardOn(t, f, []byte("firstparty.example"), "deadmeta.onion:443")
